cat /home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-17-projects-recovery-aware-struct-prune--claude-sessions-agent-174695fa/fc5ebd49-3495-4277-a661-53f82757ae37/tool-results/mcp-agent-ml-research-read_registry-1779448389149.txt | python3 -c "
import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result['data']['experiments']

# Find all MATH-500 experiments with success conclusion
math500 = {}
for k, v in exps.items():
    if 'math500' in k and v.get('conclusion') == 'success' and v.get('metrics'):
        m = v['metrics']
        acc = m.get('math500_accuracy', m.get('accuracy'))
        if acc:
            math500[k] = {'accuracy': acc, 'correct': m.get('math500_correct', m.get('correct')), 'total': m.get('math500_total', m.get('total', 500))}

for k in sorted(math500.keys()):
    v = math500[k]
    print(f'{k}: {v[\"accuracy\"]:.4f} ({v.get(\"correct\", \"?\")}/{v.get(\"total\", \"?\")})')
"
